use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock once, through the granted wall-clock capability.
        let seconds = wall_clock::now().seconds;

        // One permitted fetch. A transport failure is a value, so it yields
        // fetched = 0 rather than a trap. An out-of-allowlist URL still traps
        // at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        // Notify through the granted notifier. The ensures clause requires
        // notified == true on every produced output, so a refused notification
        // must not produce a report: trap instead.
        let message = format!("heartbeat at {seconds}: fetched {fetched} chars");
        let notified = notifier::notify(&message);
        if !notified {
            panic!("notifier refused the heartbeat");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

// Not implemented: recording `last-input` in the shared store. That requires a
// `state-rw` import, which is not in this node's `with` clause (http-client,
// notifier, wall-clock), and the node's authority is exactly that clause. The
// output above is unaffected by this omission.

export!(Node);
